import re
from typing import Dict

def modify_kickstart_config(config_file: str, parameters: Dict[str, str]):
    modified_file = ""modified_kickstart.conf""
    sed_commands = [f""s/{placeholder}/{value}/g"" for placeholder, value in parameters.items()]
    sed_commands.append(""a/new_password_line\nencrypted_password_here"")

    try:
        with open(config_file, ""r+"") as f:
            content = f.read()
            for command in sed_commands:
                content = re.sub(command, r""\g<0>"", content)
            f.seek(0)
