2,"Create a function named `generateWeatherForecasts` that accepts two parameters: `quantity` representing the number of weather forecasts to generate, and `minTemp` and `maxTemp` representing the minimum and maximum temperatures in degrees Celsius for a day. The function should return an array of `WeatherForecast` structures, each containing a random date within the last month, a randomly generated temperature between `minTemp` and `maxTemp`, and a randomly assigned weather condition from an enum called `WeatherCondition`. Ensure that memory allocation for the returned array is handled correctly to avoid memory leaks. Additionally, implement error handling for potential issues with memory allocation or data generation.",680,,"['```swift
import Foundation

enum WeatherCondition: String {
    case sunny = ""Sunny""
    case cloudy = ""Cloudy""
    case rainy = ""Rainy""
}

struct WeatherForecast {
    let date: Date
    let temperature: Double
    let weatherCondition: WeatherCondition
}

func generateWeatherForecasts(_ quantity: Int, minTemp: Double, maxTemp: Double) -> [WeatherForecast]? {
    var forecasts = [WeatherForecast]()

    for _ in 1...quantity {
        let date = Calendar.current.date(byAdding: .day, value: -30, to: Date()) // last 30 days
        let temperature = Double.random(in: minTemp...maxTemp)
        let weatherCondition = WeatherCondition.allCases.randomElement()!

        let forecast = WeatherForecast(date: date!, temperature: temperature, weatherCondition: weatherCondition)
        forecasts.append(forecast)
    }

    return forecasts
}
