0,"Create a new programming task that involves initializing and utilizing the DES (Data Encryption Standard) cipher with a given key. The task should include functions for initializing the DES cipher, encrypting a block of data, and cleaning up the cipher after use. The program should demonstrate how to encrypt a simple text message using the initialized DES cipher and then decrypt it back to its original form. Additionally, include error handling to check if the encryption or decryption process was successful.",328,,"['```python
import des3

def init_des(key):
    return des3.triple_DES.new(key, des3.MODE_ECB)

def encrypt(cipher, data):
    try:
        encrypted = cipher.encrypt(data)
        return encrypted
    except Exception as e:
        print(f""Error during encryption: {e}"")
        return None

def decrypt(cipher, data):
    try:
        decrypted = cipher.decrypt(data)
        return decrypted
    except Exception as e:
        print(f""Error during decryption: {e}"")
        return None

def main():
    key = b'1234567890123456'
    cipher = init_des(key)

    message = ""Hello, World!"".encode('utf-8')

    encrypted_message = encrypt(cipher, message)
    if encrypted_message is not None:
        print(""Encrypted Message:"", encrypted_message.hex())

        decrypted_message = decrypt(cipher, encrypted_message)
        if decrypted_message is not None:
            print(""Decrypted Message:"", decrypted_message.decode('utf-8'))

if __name__ == ""__main__"":
    main()
```

