import base64
import hashlib
from Crypto.Cipher import TripleDES
from Crypto.Util import Padding
import logging
from collections import defaultdict

class Serializable:
    factories = defaultdict(lambda: None)
    registry = {}

    def __init__(self, data=None):
        if data is not None and isinstance(data, bytes):
            self.deserialize(data)

    @staticmethod
    def register_factory(id_, factory):
        Serializable.registry[id_] = factory

    @classmethod
    def create(cls, id_, **kwargs):
        return cls.registry[id_](**kwargs)

    @classmethod
    def add_factory(cls, factory_function):
        for subclass in cls.__subclasses__():
            Serializable.factories[subclass.__name__] = factory_function

    def serialize(self):
        return bytes(repr(self))

    @staticmethod
    def deserialize(data):
        try:
            obj = pickle.loads(data)
            if isinstance(obj, Serializable):
                return obj
        except (TypeError, EOFError, pickle.UnpicklingError):
            pass
        return None

    @staticmethod
    def decrypt_and_hash(encrypted_message, key, iv):
        cipher = TripleDES.new(key, TripleDES.MODE_CBC, iv)
        plaintext = base64.b64decode(encrypted_message).decrypt(cipher)
        message = Padding.unpad(plaintext, Padding.PKCS5)
        md5_hash = hashlib.md5(message).hexdigest()
        return md5_hash[:8], md5_hash

class EncryptedJSON(Serializable):
    @staticmethod
    def decrypt_json(json_data, key, iv):
        encrypted_message = base64.b64decode(json_data['encryptedData'])
        _, md5_hash = Serializable.decrypt_and_hash(encrypted_message, key, iv)
        if json_data['md5Hash'] != md5_hash:
            raise ValueError(""Incorrect MD5 hash."")
        return json.loads(json_data['plaintext'])

    @staticmethod
    def encrypt_json(obj, key, iv):
        plaintext = json.dumps(obj)
        _, md5_hash = Serializable.decrypt_and_hash(plaintext, key, iv)
        return {'encryptedData': base64.b64encode(plaintext).decode(), 'md5Hash': md5_hash}

    def __init__(self, json_data=None):
        if json_data is not None:
            self.json_data = EncryptedJSON.decrypt_json(json_data, key, iv)

logger = logging.getLogger(__name__)

def main():
    # Deserialize and decrypt JSON data with Triple DES encryption and compute MD5 hash.
    data = EncryptedJSON({'encryptedData': 'base64-encoded-message', 'md5Hash': 'existing_hash'})
    obj = data.json_data  # Use the deserialized object directly.
    md5_hash, checksum = Serializable.decrypt_and_hash(obj['message'], key, iv)

    # Logging mechanism for debugging purposes.
    logger.info(f""Decrypted message: {obj}, MD5 hash: {md5_hash}, Checksum: {checksum}"")
