from Crypto.Cipher import TripleDES
from Crypto.Util.Padding import pad, unpad
import logging
from typing import Dict, Callable, Any

class SecureSerializer:
    _factories = {}

    def __init__(self):
        self.logger = logging.getLogger(__name__)

    @staticmethod
    def add_factory(id: str, factory: Callable[[], object]):
        SecureSerializer._factories[id] = factory

    @staticmethod
    def create_instance(id: str, **kwargs) -> Any:
        return SecureSerializer._factories.get(id, None)(**kwargs)

    def encrypt_message(self, message: bytes, key: bytes, iv: bytes):
        cipher = TripleDES.new(key, TripleDES.MODE_CBC, iv)
        return base64.b64encode(cipher.encrypt(pad(message, TripleDES.block_size)))

    def decrypt_message(self, encrypted: bytes, key: bytes, iv: bytes):
        cipher = TripleDES.new(key, TripleDES.MODE_CBC, iv)
        return unpad(cipher.decrypt(base64.b64decode(encrypted)), TripleDES.block_size)

    def compute_md5(self, data: bytes) -> str:
        md5 = hashlib.md5()
        md5.update(data)
        return md5.hexdigest()[:8] + '-' + md5.hexdigest()[8:].upper()

    def deserialize_object(self, serialized_bytes: bytes):
        try:
            with open(io.BytesIO(serialized_bytes), 'rb') as f:
                return pickle.load(f)
        except Exception as e:
            self.logger.error(f'Error deserializing object: {e}')
            raise

    def serialize_object(self, obj: Any):
        try:
            serialized = pickle.dumps(obj)
            return base64.b64encode(serialized).decode()
        except Exception as e:
            self.logger.error(f'Error serializing object: {e}')
            raise

    def get_checksum(self, data: bytes) -> str:
        return self.compute_md5(data)

