0,"Develop a Python script that integrates functionality for extracting metadata from a given directory of image files, resizing selected images to specified dimensions, and applying a grayscale conversion. The script should include options for user-defined output directory and image quality settings. It should also handle exceptions related to inaccessible directories or unsupported image formats, logging detailed error messages for debugging purposes. Furthermore, the script should offer the capability to create a thumbnail version of each resized image, with adjustable dimensions for optimal preview representation in applications requiring thumbnail functionality.",242,,"[""```python
import os
import sys
from PIL import Image, ImageEnhance
from io import BytesIO
import argparse
from tqdm import tqdm
import logging

def is_supported_format(file):
    return file.lower().endswith(('jpg', 'jpeg', 'png'))

def resize_image(img, width, height):
    return img.resize((width, height), Image.ANTIALIAS)

def apply_grayscale(img):
    return img.convert('L')

def save_image(img, output_dir, filename, quality=90):
    img_bytes = BytesIO()
    img.save(img_bytes, format='JPEG' if filename.endswith('.jpg') else 'PNG', quality=quality)
    with open(os.path.join(output_dir, filename), 'wb') as f:
        f.write(img_bytes.getvalue())

def create_thumbnail(img, thumbnail_size):
    return img.resize(thumbnail_size, Image.ANTIALIAS)

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('input_dir', help='Input directory containing image files')
    parser.add_argument('output_dir', help='Output directory for processed images')
    parser.add_argument('--thumbnail_size', type=int, nargs=2, metavar=('W', 'H'), default=(100, 100), help='Thumbnail size for each image (default: %(default)s)')
    args = parser.parse_args()

    if not os.path.exists(args.input_dir):
        logging.error(f'Input directory does not exist: {args.input_dir}')
        sys.exit(1)

    if not os.path.exists(args.output_dir):
        os.makedirs(args.output_dir, exist_ok=True)

    for file in tqdm(os.listdir(args.input_dir)):
        try:
            with Image.open(os.path.join(args.input_dir, file)) as img:
                if not is_supported_format(file):
                    logging.warning(f'Unsupported image format for {file}. Skipping...')
                    continue
                resized_img = resize_image(img, args.thumbnail_size[0], args.thumbnail_size[1])
                thumbnail = create_thumbnail(resized_img, *args.thumbnail_size)
                grayscale_img = apply_grayscale(resized_img)
                save_image(grayscale_img, args.output_dir, file)
                save_image(thumbnail, args.output_dir, f'{file[:-3]}_thumbnail{args.thumbnail_size[0]}x{args.thumbnail_size[1]}', quality=85)
        except Exception as e:
            logging.error(f'An error occurred while processing image {file}: {e}')

if __name__ == '__main__':
    main()
```

