                                    max_lower",377,,"[' ```python
import random
import string

def secure_password_generator(length, upper_bound=20,
                               min_upper=1, max_upper=3,
                               min_lower=1, max_lower=3,
                               min_digits=1, max_digits=3,
                               min_special=1, max_special=3):
    allowed_chars = {
        'upper': string.ascii_uppercase,
        'lower': string.ascii_lowercase,
        'digits': string.digits,
        'special': ""!@#$%^&*()-_+=<>,./?""
    }

    category_ranges = {
        'upper': (min_upper, max_upper),
        'lower': (min_lower, max_lower),
        'digits': (min_digits, max_digits),
        'special': (min_special, max_special)
    }

    password = []

    for _ in range(length):
        category_counts = {k: v[1] - v[0] + 1 for k, v in category_ranges.items()}
        remaining = upper_bound - sum(category_counts.values())
        if remaining > 0:
            category_counts['special'] -= min(remaining, category_counts['special'])

        for cat, count in category_counts.items():
            password.append(random.choice(allowed_chars[cat]))

    return ''.join(password)
```

