import ast
from ast import *
from os import path
from sys import argv
from lark import Lark, Transformer

class Parser(Transformer):
    def __init__(self):
        self.code = []

    def prog(self, p):
        for stmt in p[0]:
            self.code += self.visit(stmt)
        return '\n'.join(self.code)

    def stmt(self, p):
        if isinstance(p[0], Label):
            return f'{p[0].name}:' + self.visit(p[1])
        elif isinstance(p[0], Assign):
            return f'{p[1].id} = {self.visit(p[2])}'
        elif isinstance(p[0], ExprStmt):
            return self.visit(p[0])
        elif isinstance(p[0], IfStmt):
            test, body, oelse = p[0]
            cond = self.visit(test)
            bcond = self.visit(body)
            ocond = None if len(oelse) == 0 else self.visit(oelse[0])
            return f'if ({cond}) \n    {bcond}\n{ocond}' if ocond is not None else f'if ({cond}) \n    {bcond}'
        elif isinstance(p[0], ForStmt):
            var, start, stop, step, body = p[0]
            init, cond, incr = self.visit([var, '=', self.visit(start), None]) if len(start) == 3 else (init := self.visit(start), '')
            cond_str, incr_str = cond, incr if len(incr) > 0 else ''
            body_str = self.visit(body[0])
            return f'for ({init}) {cond_str} ({incr_str}) \n    {body_str}'
        elif isinstance(p[0], FuncDef):
            name, args, body = p[0]
            params = ', '.join([arg.name for arg in args]) if args else ''
            return f'def {name}({params}):\n    {self.visit(body)}\n'
        elif isinstance(p[0], CallStmt):
            func, args = p[0]
            params = ', '.join([arg.id for arg in args]) if args else ''
            return f'{func}({params})'
        elif isinstance(p[0], ReturnStmt):
            value = self.visit(p[0].value) if len(p[0]) > 0 else ''
            return f'return {value}'
        elif isinstance(p[0], PassStmt):
            return ''
        raise ValueError('Unexpected statement type')

    def expr(self, p):
        if isinstance(p[0], Num):
            return str(p[0].n)
        elif isinstance(p[0], AddOp):
            return self.visit(p[1]) + ' + ' + self.visit(p[2])
        elif isinstance(p[0], SubOp):
            return self.visit(p[1]) + ' - ' + self.visit(p[2])
        elif isinstance(p[0], MulOp):
            return self.visit(p[1]) + ' * ' + self.visit(p[2])
        elif isinstance(p[0], DivOp):
            return self.visit(p[1]) + ' / ' + self.visit(p[2])
        elif isinstance(p[0], ModOp):
            return self.visit(p[1]) + ' % ' + self.visit(p[2])
        elif isinstance(p[0], UshrOp):
            return self.visit(p[1]) + ' >> ' + self.visit(p[2])
        elif isinstance(p[0], LshrOp):
            return self.visit(p[1]) + ' << ' + self.visit(p[2])
        elif isinstance(p[0], AndOp):
            return self.visit(p[1]) + ' & ' + self.visit(p[2])
        elif isinstance(p[0], OrOp):
            return self.visit(p[1]) + ' | ' + self.visit(p[2])
        elif isinstance(p[0], XorOp):
            return self.visit(p[1]) + ' ^ ' + self.visit(p[2])
        elif isinstance(p[0], EqOp):
            return f'({self.visit(p[1])} == {self.visit(p[2])})'
        elif isinstance(p[0], NeqOp):
            return f'({self.visit(p[1])} != {self.visit(p[2])})'
        elif isinstance(p[0], LtOp):
            return f'({self.visit(p[1])} < {self.visit(p[2])})'
        elif isinstance(p[0], GtOp):
            return f'({self.visit(p[1])} > {self.visit(p[2])})'
        elif isinstance(p[0], LteOp):
            return f'({self.visit(p[1])} <= {self.visit(p[2])})'
        elif isinstance(p[0], GteOp):
            return f'({self.visit(p[1])} >= {self.visit(p[2])})'
        elif isinstance(p[0], NotOp):
            return f'!{self.visit(p[1])}'
        elif isinstance(p[0], NegOp):
            return f'-{self.visit(p[1])}'
        elif isinstance(p[0], CallExpr):
            func, args = p[0]
            params = ', '.join([arg.id for arg in args]) if args else ''
            return f'{func}({params})'
        elif isinstance(p[0], Identifier):
            return p[0].s
        elif isinstance(p[0], LabelRef):
            return p[0].name
        elif isinstance(p[0], IndexExpr):
            return f'[{self.visit(p[1])}]'
        else:
            raise ValueError('Unexpected expression type')

def generate_object_code(file_path):
    if not path.isfile(file_path):
        raise FileNotFoundError(f'File {file_path} does not exist')

    with open(file_path, 'r') as f:
        code = f.read()

    try:
        tree = ast.parse(code)
        visitor = Parser()
        object_code = visitor.visit(tree)
    except Exception as e:
        raise ValueError(f'Parsing error: {e}')

    return object_code
```

