def update_complex_dict(input_dict, key_operations):
    allowed_operations = {'concat': str, 'replace': str, 'new_entry': None}
    invalid_operation_msg = ""Invalid operation specified: {}""

    for key, value in key_operations.items():
        if key not in allowed_operations:
            raise ValueError(invalid_operation_msg.format(key))

        operation = key_operations[key]
        if operation == 'concat':
            if key in input_dict:
                input_dict[key] += value
            else:
                input_dict[key] = value
        elif operation == 'replace':
            input_dict[key] = value
        elif operation == 'new_entry':
            input_dict[key] = value

