import pygame
import sys
from typing import List, Dict

pygame.init()

def draw_shapes(shape_data: List[Dict], width=800, height=600):
    shapes = {}
    errors = []

    screen = pygame.display.set_mode((width, height))

    def is_valid_color(color):
        if len(color) == 3 and all([0 <= x <= 255 for x in color]):
            return True
        return False

    def is_valid_position(pos):
        if len(pos) == 2 and 0 <= pos[0] < width and 0 <= pos[1] < height:
            return True
        return False

    def is_valid_size(size):
        if type(size) is int and size > 0:
            return True
        return False

    for shape in shape_data:
        try:
            if not isinstance(shape, dict):
                raise ValueError(""Shape data must be a dictionary."")

            if 'type' not in shape or (shape['type'] not in ('rectangle', 'circle')):
                raise KeyError(""Shape type must be either 'rectangle' or 'circle'."")

            if 'color' not in shape or not is_valid_color(shape['color']):
                errors.append(f""Invalid color for shape {shape}"")
                continue

            if 'position' not in shape or not is_valid_position(shape['position']):
                errors.append(f""Invalid position for shape {shape}"")
                continue

            if 'size' not in shape or not is_valid_size(shape['size']):
                errors.append(f""Invalid size for shape {shape}"")
                continue

            shapes[shape['id']] = shape
        except KeyError as e:
            print(e)

    if errors:
        print(""The following shape properties have errors:"", "", "".join(errors))
        return

    clock = pygame.time.Clock()

    running = True
    animation_speed = 5
    animation_dir = [1, 0]

    while running:
        for event in pygame.event.get():
            if event.type == pygame.QUIT:
                running = False

        screen.fill((0, 0, 0))

        for shape_id, shape in shapes.items():
            if shape['type'] == 'rectangle':
                rect = pygame.Rect(shape['position'], (shape['size'], shape['size']))
                pygame.draw.rect(screen, shape['color'], rect)
            elif shape['type'] == 'circle':
                circle = pygame.draw.circle(screen, shape['color'], shape['position'], shape['size'], 0)
                # Fill the circle with color
                pygame.draw.rect(circle, shape['color'], (0, 0, *circle.get_size()))

            if 'animation' in shape and shape['animation']:
                x, y = shape['position']
                new_x, new_y = x + animation_speed * animation_dir[0], y + animation_speed * animation_dir[1]

                if new_x < 0 or new_x > width - shape['size'] or new_y < 0 or new_y > height - shape['size']:
                    # Reset the direction when it hits the edge
                    animation_dir = [abs(animation_dir[0]), abs(animation_dir[1])]
                else:
                    shape['position'] = (new_x, new_y)

        pygame.display.flip()
        clock.tick(60)

    pygame.quit()
    sys.exit()
