import hashlib
import sys

def read_binary_file(filename):
    with open(filename, 'rb') as file:
        return file.read()

def transform_data(data, rules):
    for rule in rules.split("",""):
        if rule == ""upper"":
            data = data.upper()
        elif rule == ""lower"":
            data = data.lower()
        elif re.search(r'^[a-zA-Z0-9]+$', rule):
            data = bytes([int(c) for c in rule if c.isdigit() or c.isalpha()])
    return data

def write_to_output_file(output_filename, data):
    with open(output_filename + ""_transformed"", 'wb') as output_file:
        output_file.write(data + b""\nSHA-256: "" + hashlib.sha256(data).hexdigest().encode())

def process_binary_file(input_filename, output_filename, rules):
    input_data = read_binary_file(input_filename)
    transformed_data = transform_data(input_data, rules)
    write_to_output_file(output_filename, transformed_data)

if __name__ == ""__main__"":
    import re
    if len(sys.argv) != 4:
        print(""Usage: python script.py <input-file> <output-file> <rules>"")
        sys.exit(1)

    process_binary_file(sys.argv[1], sys.argv[2], sys.argv[3])
```

