```python
import os
from cryptography.hazmat.primitives.ciphers import Cipher, algorithms, modes
from cryptography.hazmat.primitives.kdf.pbkdf2 import PBKDF2HMAC
from cryptography.hazmat.exceptions import InvalidSignature, InvalidTag
from cryptography.hazmat.primitives import hashes

class DES_Cipher:
    def __init__(self, key):
        self.key = key.encode()
        self._kdf = PBKDF2HMAC(
            algorithm=hashes.SHA256(),
            length=32,
            salt=b'salt',
            iterations=100000,
        )
        self.cipher = None

    def initialize_cipher(self):
        try:
            derived_key = self._kdf.derive(self.key)
            self.cipher = Cipher(algorithms.TripleDES(derived_key[:24]), modes.ECB())
            return derived_key[:8]
        except Exception as e:
            raise ValueError(f""Error while initializing cipher: {str(e)}"")

    def encrypt_data(self, data):
        try:
            encryptor = self.cipher.encryptor()
            encrypted_data = encryptor.update(data.encode()) + encryptor.finalize()
            return encrypted_data
        except Exception as e:
            raise ValueError(f""Error while encrypting data: {str(e)}"")

    def decrypt_data(self, encrypted_data):
        try:
            decryptor = self.cipher.decryptor()
            decrypted_data = decryptor.update(encrypted_data) + decryptor.finalize()
            return decrypted_data.decode()
        except (InvalidSignature, InvalidTag) as e:
            raise ValueError(f""Error while decrypting data: {str(e)}"")

    def cleanup(self):
        if hasattr(self, 'cipher'):
            delattr(self, 'cipher')
