0,"Create a Python class for generating distinctive session tokens for user authentication. The class must accept user IDs and produce cryptographically secure tokens using a self-defined hash function anchored in the SHA-256 algorithm. Ensure that each token produced corresponds uniquely to the provided user ID, and include a feature to ascertain if two tokens pertain to the same user. Moreover, incorporate a capability to record all generated tokens alongside their corresponding user IDs for audit purposes.",680,,"['```python
import hashlib
import uuid
from typing import Dict

class SessionToken:
    def __init__(self):
        self._tokens = {}

    def generate_token(self, user_id: str) -> str:
        token = hashlib.sha256((str(user_id)+str(uuid.uuid4())).encode()).hexdigest()
        self._tokens[token] = user_id
        return token

    def compare_tokens(self, token1: str, token2: str) -> bool:
        return self._tokens.get(token1, None) == self._tokens.get(token2, None)

    def get_user_id_by_token(self, token: str) -> str:
        if token in self._tokens:
            return self._tokens[token]
        return None
```']",0,[0],[],True,0,0,0,

