class TaskManager:
    def __init__(self):
        self.task_queue = []
        self.node_manager = NodeManager()

    def submit_task(self, task):
        self.task_queue.append(task)

    def allocate_tasks(self):
        for node in self.node_manager.get_available_nodes():
            task = self.task_queue.pop(0)  # dequeue the highest priority task
            if self._can_allocate(node, task):
                task.current_node = node.id
                node.working_tasks.append(task)

    def _can_allocate(self, node, task):
