        self.user_id = user_id
        self.tokens = set()
        self.audit_log = []

    def generate(self):
        token = str(uuid.uuid4()).replace('-', '') + hashlib.sha256(str(self.user_id).encode()).hexdigest()
        while token in self.tokens:
            token = str(uuid.uuid4()).replace('-', '') + hashlib.sha256(str(self.user_id).encode()).hexdigest()
        self.tokens.add(token)
        self.audit_log.append((token, self.user_id, datetime.now()))
        return token

    def check_same_user(self, token1, token2):
        return (token1 in self.tokens and token2 in self.tokens and self.tokens[token1] == self.tokens[token2])
