import math

def sieve_of_eratosthenes(n):
    primes = [True for _ in range(n+1)]
    primes[0] = primes[1] = False
    for p in range(2, int(n**0.5) + 1):
        if primes[p]:
            for i in range(p*p, n+1, p):
                primes[i] = False
    return [p for p in range(2, n+1) if primes[p]]

def is_perfect_square(n):
    return math.isqrt(n)**2 == n

def check_sum_perfect_square(start, end):
    primes = sieve_of_eratosthenes(max(end, int(math.sqrt(end))+1))
    sum_primes = sum(prime for prime in primes if start <= prime <= end)
    return is_perfect_square(sum_primes)
```

