        result = []

        def traverse(obj, current_keys=[]):
            if len(current_keys) == len(keys):
                if all([k == current_keys[-1] for k in keys]):
                    result.append(obj)
                return

            for key, val in obj.items():
                if isinstance(val, list):
                    for item in val:
                        traverse(item, current_keys + [key])
                elif isinstance(val, dict):
                    traverse(val, current_keys + [key])

        traverse(data)
        return result if len(result) > 1 else result[0]
    except json.JSONDecodeError:
        return None

