import random
import string
from typing import List

def generate_user(total: int, age_range: tuple, gender_ratio: float) -> List[dict]:
    users = []

    for _ in range(total):
        username = ''.join(random.choice(string.ascii_letters + '_') for _ in range(10))
        user = {'username': username, 'email': f'{username}@example.com', 'age': random.randint(*age_range), 'gender': random.choice(['male', 'female']) if random.random() < gender_ratio/2 else 'non-binary'}

        while user in users:
            username = ''.join(random.choice(string.ascii_letters + '_') for _ in range(10))
            user['username'] = username

        users.append(user)

    return sorted(users, key=lambda x: x['age'])

def verify_data(users: List[dict]) -> None:
    unique_usernames = set()

    for user in users:
        if user['username'] not in unique_usernames:
            unique_usernames.add(user['username'])
        else:
            print(""Error: Non-unique username."")
            raise ValueError(""Non-unique username."")

        if len(set([user['gender'], 'non-binary'] if user['gender'] not in ['male', 'female'] else user['gender']) & set(['male', 'female'])) < 1:
            print(""Error: Invalid gender."")
            raise ValueError(""Invalid gender."")

        if min([user['age'] for user in users]) < min(*age_range) or max([user['age'] for user in users]) > max(*age_range):
            print(""Error: User age out of range."")
            raise ValueError(""User age out of range."")
