6. Offers the feature to generate thumbnail versions of each resized image, with adjustable dimensions suitable for efficient preview in applications requiring thumbnail functionality.",242,,"['```python
import os
import sys
from PIL import Image, ImageEnhance, ImageGrab
from io import BytesIO
from zipfile import ZipFile
import shutil
from tqdm import tqdm

def extract_metadata(image_path):
    image = Image.open(image_path)
    return {
        'filename': image.filename,
        'format': image.format,
        'size': image.size,
        'mode': image.mode
    }

def resize_image(image, width, height):
    return image.resize((width, height), Image.ANTIALIAS)

def convert_to_grayscale(image):
    return image.convert('L')

def save_image(image, output_path, quality=90):
    image.save(output_path, format='JPEG', quality=quality)

def generate_thumbnail(image, thumbnail_size=(128, 128)):
    return image.resize(thumbnail_size, Image.ANTIALIAS)

def main():
    input_dir = 'path/to/input/directory'
    output_dir = 'path/to/output/directory'
    thumbnail_size = (320, 240)

    if not os.path.exists(input_dir):
        print(f""Error: Input directory '{input_dir}' does not exist."")
        sys.exit()

    os.makedirs(output_dir, exist_ok=True)

    image_formats = {'jpg', 'jpeg', 'png'}

    images = []
    for root, dirs, files in os.walk(input_dir):
        for file in files:
            if file.lower().endswith(tuple(image_formats)):
                image_path = os.path.join(root, file)
                try:
                    image = Image.open(image_path)
                    metadata = extract_metadata(image_path)
                    images.append((image, metadata))
                except Exception as e:
                    print(f""Error processing {image_path}: {e}"")

    for image, metadata in tqdm(images):
        resized_image = resize_image(convert_to_grayscale(image), *thumbnail_size)
        thumbnail_path = os.path.join(output_dir, f'{metadata[""filename""]}_thumbnail.jpg')
        save_image(resized_image, thumbnail_path)

        resized_image = resize_image(convert_to_grayscale(image), 800, 600)
        output_path = os.path.join(output_dir, metadata[""filename""])
        save_image(resized_image, output_path)

if __name__ == '__main__':
    main()
