def read_and_sort_file(file_path):
    try:
        with open(file_path) as f:
            lines = f.readlines()
            lines.sort(key=lambda x: int(x.split("":"")[1].strip()), reverse=True)
            if len(lines) > 0:
                last_line = lines[-1]
                return int(last_line.split("":"")[1].strip())
