    :param file_path: Path to the XML file
    :param target_tags: List of tag names to extract data for
    :return: A nested dictionary containing extracted data
    """"""

    cache_file = f""{file_path}.cache""

    if os.path.isfile(cache_file) and os.path.getmtime(cache_file) > os.path.getmtime(file_path):
