        else:
            data = {}

    invalid_tags = set(target_tags) - set([t for t in tree.getroot().iter()])
    if invalid_tags:
        print(f""Error: Invalid tags provided: {invalid_tags}"")
        return {}

    filtered_data = {}
    for tag, texts in data.items():
        if tag[0] in target_tags:
            filtered_data[tag] = texts

    return filtered_data

def load_tree(file_path):
    try:
        tree = ElementTree().parse(file_path)
        return tree
    except Exception as e:
        print(f""Error loading tree: {e}"")
        return None

def build_dictionary(element_tree):
    if element_tree is None:
        return {}

    result = {}
    stack = [(element_tree, (), [])]

    while stack:
        current_element, parents_stack, texts_stack = stack.pop()

        current_tag = (current_element.tag,) + parents_stack

        if current_element.text:
            texts_stack.append(current_element.text)

        if len(current_element) > 0:
            for child in current_element:
                stack.append((child, (*parents_stack, current_tag[1]), texts_stack[:]))

        result[current_tag] = texts_stack

    return result
