import pandas as pd

class TextAnalyzer:
    def __init__(self, language, preprocessing_steps=None, training_dataset=None):
        self.language = language
        self.preprocessing_steps = preprocessing_steps or []
        self.training_dataset = training_dataset
        self.vectorizer = None
        self.classifier = None

    def _apply_preprocessing(self, text):
        for step in self.preprocessing_steps:
            if callable(step):
                text = step(text)
            else:
                nltk.download(step)
                text = nltk.text.TextTokenizer().tokenize(text)
                text = [nltk.stem.WordNetLemmatizer().lemmatize(word) for word in text]
        return text

    def fit(self, X, y):
        self.vectorizer = TfidfVectorizer() if self.language == 'english' else CountVectorizer()
        self.classifier = RandomForestClassifier()  # Change this to your preferred model
        self.classifier.fit(self._apply_preprocessing(X), y)

    def predict(self, X):
        return self.classifier.predict(self._apply_preprocessing(X))

    def evaluate(self, X, y):
        y_pred = self.predict(X)
        accuracy = accuracy_score(y, y_pred)
        precision = precision_score(y, y_pred)
        recall = recall_score(y, y_pred)
        f1 = f1_score(y, y_pred)
        cm = confusion_matrix(y, y_pred)
        return {'accuracy': accuracy, 'precision': precision, 'recall': recall, 'f1': f1, 'confusion matrix': cm}

    def analyze(self, X, y=None):
        category_word_counts = {}
        for category in set(y):
            category_data = X[y == category]
            words = nltk.FreqDist(nltk.text.TextTokenizer().tokenize(category_data))
            category_word_counts[category] = {word: count for word, count in words.items() if count > 5}
        sentiment_scores = self.predict(X)
        positive_documents = X[sentiment_scores == 1]
        negative_documents = X[sentiment_scores == 0]
        report = {
            'category word counts': category_word_counts,
            'sentiment insights': {
                'positive documents': len(positive_documents),
                'negative documents': len(negative_documents)
            }
        }
        return pd.DataFrame(report)
