def encodeMessage(plaintext, key):
    if not isinstance(plaintext, str) or not isinstance(key, int):
        return ""Error: Invalid input. Both plaintext and key must be strings.""

    encoded_message = """"

    for char in plaintext:
        if char.isalpha():
            shifted_char = chr(((ord(char.upper()) - 65 + int(key) % 26) % 26) + 65)
            encoded_message += shifted_char if char.islower() else shifted_char.lower()
        else:
            encoded_message += char

    return encoded_message
