import os
import subprocess

def create_virtual_environment(project_name):
    venv_path = f""{project_name}_venv""
    if not os.path.exists(venv_path):
        subprocess.run(['python3', '-m', 'venv', venv_path])

def install_dependencies(venv_path, dependencies=['numpy', 'pandas', 'matplotlib']):
    with open(f""{venv_path}/bin/activate"", ""w"") as f:
        pass
    activated_path = os.path.join(venv_path, ""bin"", ""activate"")
    os.chdir(venv_path)
    subprocess.run([activated_path, 'source', './bin/activate'])
    subprocess.run(['pip3', 'install'] + dependencies)

def main():
    project_name = ""myproject""
    create_virtual_environment(project_name)
    install_dependencies(project_name)

if __name__ == ""__main__"":
