from flask import Flask, jsonify, request
import json
import yaml
import csv
from json2csv import Writer

app = Flask(__name__)

def parse_json(data):
    try:
        obj = json.loads(data)
        return extract_data(obj, keys)
    except Exception as e:
        print(f'Error parsing JSON: {e}')
        return []

def extract_data(obj, keys):
    result = []

    def traverse(current_object, current_keys):
        if not current_keys:
            result.append(current_object)
            return

        key = current_keys[0]
        if key in current_object and isinstance(current_object[key], dict) or isinstance(current_object[key], list):
            current_keys.insert(0, key)
            for item in (current_object[key] if isinstance(current_object[key], list) else [current_object[key]]):
                traverse(item, current_keys)
        else:
            current_keys.pop(0)

    keys = list(set(keys))

    for obj in (obj,):
        keys.forEach((k) => traverse(obj, [k]))

    return result

@app.route('/parseJSON', methods=['POST'])
def parse_json_endpoint():
    data = request.get_json()['data']
    keys = request.get_json()['keys'] if 'keys' in request.get_json() else []

    parsed_data = parse_json(data)

    return jsonify(parsed_data)

app.run(debug=True)
