class Pet:
    def __init__(self, species, breed, age):
        self._species = species
        self._breed = breed
        self._age = age

    @property
    def species(self):
        return self._species

    @species.setter
    def species(self, value):
        if not isinstance(value, str):
            raise TypeError(""Species must be a string."")
        self._species = value

    @property
    def breed(self):
        return self._breed

    @breed.setter
    def breed(self, value):
        if not isinstance(value, str):
            raise TypeError(""Breed must be a string."")
        self._breed = value

    @property
    def age(self):
        return self._age

    @age.setter
    def age(self, value):
        if not isinstance(value, int) or value < 0:
            raise ValueError(""Age must be a non-negative integer."")
        self._age = value

    def display_pet_details(self):
        return f""Pet Details:\nSpecies: {self.species}\nBreed: {self.breed}\nAge: {self.age}""
```

